package com.bank.batch.service;

import java.util.logging.Logger;

// Finds the next cyclic batch code strictly greater than the current.
public class BatchCodeService {
    private static final Logger log = Logger.getLogger(BatchCodeService.class.getName());

    public char nextCode(char[] codes, char current) {
        int n = codes.length;
        int start = 0, end = n - 1;
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (current >= codes[mid]) start = mid + 1; // skip equal, seek strictly greater
            else end = mid - 1;
        }
        char next = codes[start % n]; // wrap around with modulo
        log.info(() -> "Next code after " + current + " is " + next);
        return next;
    }
}
