package com.bank.batch;

import com.bank.batch.service.BatchCodeService;
import java.util.logging.Logger;

public class BatchCodeApplication {
    private static final Logger log = Logger.getLogger(BatchCodeApplication.class.getName());

    public static void main(String[] args) {
        BatchCodeService service = new BatchCodeService();
        char[] codes = {'a', 'c', 'f', 'h'};
        log.info("After f: " + service.nextCode(codes, 'f'));
        log.info("After h (wraps): " + service.nextCode(codes, 'h'));
    }
}
